parameters.query:
SELECT id, username, keywords
FROM users
WHERE id = $1::uuid AND active;

parameters.jsCode:
// Une seule entrée pour le LLM : la liste compacte des candidats (id | sujet | source | titre)
const user = $('Utilisateur').first().json;
const news = $input.all().map(i => i.json).filter(n => n.id);
if (news.length === 0) return [];   // rien de neuf pour cet utilisateur
const list = news.map(n => `${n.id} | ${n.topic_slug} | ${n.source} | ${n.title}`).join('\n');
return [{ json: { user_id: user.id, keywords: user.keywords || [], count: news.length, list } }];

parameters.text:
=Tu sélectionnes les articles d'une newsletter personnalisée.
Mots-clés de l'utilisateur : {{ $json.keywords.length ? $json.keywords.join(', ') : 'aucun' }}

Articles candidats (id | sujet | source | titre) :
{{ $json.list }}

Choisis les 6 articles les plus intéressants pour cet utilisateur : en priorité ceux qui correspondent à ses mots-clés, puis les informations les plus importantes. Varie les sujets et les sources, et ne prends jamais deux articles sur le même événement.
Réponds uniquement avec un objet JSON de la forme {"ids": [12, 7, 3]} contenant 6 id pris dans la liste.

parameters.jsCode:
// Garde-fou : on ne garde que des id présents dans les candidats (le LLM ne peut rien inventer),
// et si sa réponse est invalide ou incomplète on complète avec les news les plus récentes.
const MAX = 6;
const cands = $('Candidats').all().map(i => i.json).filter(n => n.id);
const byId = new Map(cands.map(n => [String(n.id), n]));
let ids = [];
try {
  // Avec le format JSON d'Ollama, la chaîne renvoie déjà { ids: [...] } ; sinon du texte à parser
  let out = Array.isArray($json.ids) ? $json : $json.text;
  if (typeof out === 'string') {
    const m = out.match(/\{[\s\S]*\}/);
    out = JSON.parse(m ? m[0] : out);
  }
  ids = ((out && out.ids) || []).map(String);
} catch (e) {}
const picked = [...new Set(ids)].filter(id => byId.has(id)).slice(0, MAX).map(id => byId.get(id));
for (const n of cands) {
  if (picked.length >= MAX) break;
  if (!picked.includes(n)) picked.push(n);
}
return picked.map(n => ({ json: n }));
